static const char *tgtr_lookup(const char *s, int l)
{
    if (!lang_ok(l)) return 0;
    for (unsigned i = 0; i < sizeof TGTR / sizeof TGTR[0]; i++) if (!strcmp(TGTR[i][0], s)) return TGTR[i][1 + l];
    return 0;
}
